def set_user_role(user_id: int):
    payload = request.get_json(silent=True) or {}
    new_role = payload.get("role", "user")
    session = get_session()
    user = session.get(User, user_id)
    if user is None:
        return jsonify({"error": "not found"}), 404
    user.role = new_role
    session.commit()
    return jsonify(user.to_dict())
